selector_to_html = {"a[href=\"Hole.html#pyskyfire.injector.element.Hole\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.element.Hole\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.element.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Hole</span></span></dt><dd><p>One hole of an element, placed in the element\u2019s own frame.</p><p>The frame has its origin at the element centre on the face, +x along the\nchamber axis into the chamber, and +y along the element\u2019s orientation.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">exit</span></code> is where the hole meets the face [m], <code class=\"docutils literal notranslate\"><span class=\"pre\">direction</span></code> a unit\nvector along the discharge, and <code class=\"docutils literal notranslate\"><span class=\"pre\">target</span></code> where the jet is drawn to and\nchecked against the wall: the impingement point for an impinging element.</p></dd>", "a[href=\"#pyskyfire.injector.element.Element.orifices\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.element.Element.orifices\">\n<span class=\"sig-name descname\"><span class=\"pre\">orifices</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">feed</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#list\" title=\"(in Python v3.15)\"><span class=\"pre\">list</span></a><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference internal\" href=\"../../ducts/orifice/Orifice.html#pyskyfire.ducts.orifice.Orifice\" title=\"pyskyfire.ducts.orifice.Orifice\"><span class=\"pre\">Orifice</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span></span></dt><dd><p>Every orifice fed from <code class=\"docutils literal notranslate\"><span class=\"pre\">feed</span></code>: one entry per hole, repeats included.</p></dd>", "a[href=\"#pyskyfire.injector.element.Element.holes\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.element.Element.holes\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">abstractmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">holes</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#tuple\" title=\"(in Python v3.15)\"><span class=\"pre\">tuple</span></a><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference internal\" href=\"Hole.html#pyskyfire.injector.element.Hole\" title=\"pyskyfire.injector.element.Hole\"><span class=\"pre\">Hole</span></a><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">...</span></span><span class=\"p\"><span class=\"pre\">]</span></span></span></span></dt><dd><p>Every hole of one element, in the element frame.</p></dd>", "a[href=\"JetFlow.html#pyskyfire.injector.element.JetFlow\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.element.JetFlow\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.element.</span></span><span class=\"sig-name descname\"><span class=\"pre\">JetFlow</span></span></dt><dd><p>The flow out of one hole: mass flow [kg/s], velocity [m/s], density [kg/m\u00b3].</p></dd>", "a[href=\"../../ducts/orifice/Orifice.html#pyskyfire.ducts.orifice.Orifice\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.orifice.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Orifice</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">area</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hydraulic_diameter</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A short restriction discharging into a large volume.</p><p class=\"rubric\">Notes</p><p>Use <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.circular\" title=\"pyskyfire.ducts.orifice.Orifice.circular\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">circular()</span></code></a>, <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.annular\" title=\"pyskyfire.ducts.orifice.Orifice.annular\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">annular()</span></code></a> or <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.slot\" title=\"pyskyfire.ducts.orifice.Orifice.slot\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">slot()</span></code></a> for those shapes.\nThe generic constructor takes any area, so an effective area quoted as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Cd\u00b7A</span></code> can be given as <code class=\"docutils literal notranslate\"><span class=\"pre\">Orifice(area=CdA,</span> <span class=\"pre\">cd=1.0)</span></code>.</p></dd>", "a[href=\"#pyskyfire.injector.element.Element\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.element.Element\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.element.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Element</span></span></dt><dd><p>Bases: <a class=\"reference external\" href=\"https://docs.python.org/3/library/abc.html#abc.ABC\" title=\"(in Python v3.15)\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">abc.ABC</span></code></a></p><p>Base class for injector element types.</p></dd>", "a[href=\"#pyskyfire.injector.element.Element.diagnostics\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.element.Element.diagnostics\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">abstractmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">diagnostics</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">flows</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#tuple\" title=\"(in Python v3.15)\"><span class=\"pre\">tuple</span></a><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference internal\" href=\"JetFlow.html#pyskyfire.injector.element.JetFlow\" title=\"pyskyfire.injector.element.JetFlow\"><span class=\"pre\">JetFlow</span></a><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">...</span></span><span class=\"p\"><span class=\"pre\">]</span></span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">oxidizer</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#frozenset\" title=\"(in Python v3.15)\"><span class=\"pre\">frozenset</span></a></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Mixing quantities of one element.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flows</span></code> is aligned with <a class=\"reference internal\" href=\"#pyskyfire.injector.element.Element.holes\" title=\"pyskyfire.injector.element.Element.holes\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">holes()</span></code></a>. <code class=\"docutils literal notranslate\"><span class=\"pre\">oxidizer</span></code> is the set of\nfeeds carrying oxidizer; every other feed carries fuel.</p></dd>", "a[href=\"#pyskyfire.injector.element.Element.feeds\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.element.Element.feeds\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">feeds</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#tuple\" title=\"(in Python v3.15)\"><span class=\"pre\">tuple</span></a></span></dt><dd><p>The feeds supplying this element, in the order its holes list them.</p></dd>", "a[href=\"#pyskyfire-injector-element-element\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.injector.element.Element<a class=\"headerlink\" href=\"#pyskyfire-injector-element-element\" title=\"Link to this heading\">\u00b6</a></h1>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
